from heapq import heappop, heappush


def fastest_delivery(n, roads, stations, capacity, swap_time, max_swaps, s, t):
    if s == t:
        return (0, 0)

    # Group parallel roads by (u, v) and discard non-regenerating self-loops.
    by_pair = {}
    for u, v, minutes, energy in roads:
        if u == v and energy >= 0:
            continue
        pair = (u, v)
        lst = by_pair.get(pair)
        if lst is None:
            by_pair[pair] = [(minutes, energy)]
        else:
            lst.append((minutes, energy))

    # Keep only Pareto-optimal parallel roads per (u, v), then sort outgoing
    # roads by required energy ascending to allow early loop termination.
    INF = 1 << 60
    adj = [[] for _ in range(n)]
    for (u, v), lst in by_pair.items():
        if len(lst) > 1:
            lst.sort()
            min_e = INF
            for m, e in lst:
                if e < min_e:
                    min_e = e
                    adj[u].append((e, v, m))
        else:
            m, e = lst[0]
            adj[u].append((e, v, m))

    for u in range(n):
        if len(adj[u]) > 1:
            adj[u].sort()

    station_list = sorted(set(stations)) if max_swaps > 0 and stations else []
    C = capacity + 1
    total_states = n * C

    best_time = INF
    best_swaps = -1

    # Layer k explores routes that have performed exactly k swaps.
    init_entries = [(0, s)]

    for k in range(max_swaps + 1):
        if not init_entries:
            break

        dist = [INF] * total_states
        max_charge = [-1] * n
        first_dist = [INF] * n
        heap = []

        for d0, u0 in init_entries:
            if d0 < best_time:
                idx = u0 * C + capacity
                if d0 < dist[idx]:
                    dist[idx] = d0
                    # Pack (distance, capacity - charge, junction); here charge == capacity.
                    heappush(heap, (d0 << 17) | u0)

        while heap:
            item = heappop(heap)
            d = item >> 17
            if d >= best_time:
                break
            u = item & 0x3FF
            c = capacity - ((item >> 10) & 0x7F)

            # Any earlier pop for u had distance <= d; if it also had charge >= c,
            # this state is dominated.
            if c <= max_charge[u]:
                continue
            if max_charge[u] == -1:
                first_dist[u] = d
            max_charge[u] = c

            if u == t:
                best_time = d
                best_swaps = k
                break

            for e, v, m in adj[u]:
                if c < e:
                    break
                nc = c - e
                if nc > capacity:
                    nc = capacity
                if nc <= max_charge[v]:
                    continue
                nd = d + m
                if nd >= best_time:
                    continue
                nxt = v * C + nc
                if nd < dist[nxt]:
                    dist[nxt] = nd
                    heappush(heap, (nd << 17) | ((capacity - nc) << 10) | v)

        if k == max_swaps or not station_list:
            break

        init_entries = []
        for st in station_list:
            fd = first_dist[st]
            if fd < INF:
                nd = fd + swap_time
                if nd < best_time:
                    init_entries.append((nd, st))

    if best_swaps == -1:
        return None
    return (best_time, best_swaps)

def best_context(messages, budget, max_gap, bonus):
    if budget < 0 or max_gap < 0:
        raise ValueError("budget and max_gap must be non-negative")

    n = len(messages)
    if n == 0:
        return 0

    neg_inf = -(sum(abs(v) for _, v, _ in messages) + n * abs(bonus) + 1)

    has_pinned = any(pinned for _, _, pinned in messages)
    ans = 0 if (not has_pinned and n <= max_gap) else neg_inf

    # dp[j][b] = max score for valid choices on 0..j where j is kept and kept length is b.
    dp = []
    # Two-stack sliding-window maximum over dp[i] for Way 3 (non-adjacent predecessors i <= j - 2).
    front = []  # elements: (idx, vec, running_max_vec)
    back = []   # elements: (idx, vec, running_max_vec)
    last_pinned = -1

    for j, (len_j, val_j, pin_j) in enumerate(messages):
        if j >= 2:
            vec = dp[j - 2]
            b_max = vec if not back else [a if a > b else b for a, b in zip(back[-1][2], vec)]
            back.append((j - 2, vec, b_max))

        low_i = max(0, last_pinned, j - 1 - max_gap)
        while (front or back) and (front[-1][0] if front else back[0][0]) < low_i:
            if not front:
                while back:
                    idx, vec, _ = back.pop()
                    f_max = vec if not front else [a if a > b else b for a, b in zip(front[-1][2], vec)]
                    front.append((idx, vec, f_max))
            front.pop()

        dp_j = [neg_inf] * (budget + 1)
        if len_j <= budget:
            limit = budget - len_j + 1

            if front and back:
                way3 = [a if a > b else b for a, b in zip(front[-1][2][:limit], back[-1][2][:limit])]
            elif front:
                way3 = front[-1][2][:limit]
            elif back:
                way3 = back[-1][2][:limit]
            else:
                way3 = None

            if j >= 1:
                prev_j1 = dp[j - 1]
                if way3 is not None:
                    for b in range(limit):
                        v2 = prev_j1[b]
                        best = v2 + bonus if v2 != neg_inf else neg_inf
                        v3 = way3[b]
                        if v3 > best:
                            best = v3
                        if best != neg_inf:
                            dp_j[b + len_j] = best + val_j
                else:
                    for b in range(limit):
                        v2 = prev_j1[b]
                        if v2 != neg_inf:
                            dp_j[b + len_j] = v2 + bonus + val_j

            if last_pinned == -1 and j <= max_gap:
                if val_j > dp_j[len_j]:
                    dp_j[len_j] = val_j

        dp.append(dp_j)
        if pin_j:
            last_pinned = j

    low_last = max(0, last_pinned, n - 1 - max_gap)
    for j in range(low_last, n):
        best_j = max(dp[j])
        if best_j > ans:
            ans = best_j

    return None if ans == neg_inf else ans

def min_pruning_cost(parent, demand, cap, cut_cost, critical, root_cap, penalty):
    n = len(parent)
    children = [[] for _ in range(n)]
    for v in range(1, n):
        children[parent[v]].append(v)

    # Top-down traversal order from root 0 (avoids recursion limits on deep trees)
    order = [0]
    for u in order:
        order.extend(children[u])

    INF = 10**18
    sub_demand = [0] * n
    has_critical = [False] * n
    dp_list = [[] for _ in range(n)]

    # Bottom-up tree knapsack DP
    for u in reversed(order):
        sub_d = demand[u]
        crit = bool(critical[u])
        for c in children[u]:
            sub_d += sub_demand[c]
            if has_critical[c]:
                crit = True
        sub_demand[u] = sub_d
        has_critical[u] = crit

        limit_u = root_cap if u == 0 else cap[u]
        if demand[u] > limit_u:
            continue

        dp = [INF] * (demand[u] + 1)
        dp[demand[u]] = 0

        for c in children[u]:
            c_dp = dp_list[c]
            can_cut = not has_critical[c]

            if not can_cut and not c_dp:
                dp = []
                break

            cur_max = len(dp) - 1
            c_max = (len(c_dp) - 1) if c_dp else 0
            new_max = min(limit_u, cur_max + c_max)
            new_dp = [INF] * (new_max + 1)

            if can_cut:
                cut_c_cost = cut_cost[c] + penalty * sub_demand[c]
                for w, cost_u in enumerate(dp):
                    if cost_u < INF:
                        new_dp[w] = cost_u + cut_c_cost

            if c_dp:
                valid_c = [(wc, cost_c) for wc, cost_c in enumerate(c_dp) if cost_c < INF]
                for w, cost_u in enumerate(dp):
                    if cost_u == INF:
                        continue
                    max_wc = limit_u - w
                    for wc, cost_c in valid_c:
                        if wc > max_wc:
                            break
                        total_cost = cost_u + cost_c
                        if total_cost < new_dp[w + wc]:
                            new_dp[w + wc] = total_cost

            if min(new_dp) == INF:
                dp = []
                break
            dp = new_dp

        dp_list[u] = dp

    if not dp_list[0]:
        return None
    ans = min(dp_list[0])
    return ans if ans < INF else None

from bisect import bisect_left


def earliest_arrival(connections, transfer, source, target, start_time, max_boardings):
    if source == target:
        return start_time
    if max_boardings <= 0 or not connections:
        return None

    num_stations = len(transfer)
    INF = 10**18

    # 1. Group connections by trip_id (filtering out connections departing before start_time)
    trips_dict = {}
    for trip_id, u, v, dep, arr in connections:
        if dep >= start_time:
            if trip_id in trips_dict:
                trips_dict[trip_id].append((dep, arr, u, v))
            else:
                trips_dict[trip_id] = [(dep, arr, u, v)]

    if not trips_dict:
        return None

    # 2. Sort each trip's connections by departure time and build station departure lists
    num_trips = len(trips_dict)
    trip_conns = [None] * num_trips
    trip_reached = [0] * num_trips
    station_deps = [[] for _ in range(num_stations)]

    for t_idx, conns in enumerate(trips_dict.values()):
        if len(conns) > 1:
            conns.sort()  # Sorts chronologically by dep
        trip_conns[t_idx] = conns
        trip_reached[t_idx] = len(conns)
        for c_idx, (dep, arr, u, v) in enumerate(conns):
            station_deps[u].append((dep, t_idx, c_idx))

    # If nothing ever leaves source, target is unreachable
    if not station_deps[source]:
        return None

    # Sort each station's departures in DESCENDING order of departure time.
    # Also prepare negative keys for fast binary search on the first visit to a station.
    station_neg_deps = [None] * num_stations
    for u in range(num_stations):
        deps = station_deps[u]
        if deps:
            deps.sort(reverse=True)
            station_neg_deps[u] = [-x[0] for x in deps]

    # station_ptr[u] tracks the prefix of station_deps[u] already processed
    station_ptr = [0] * num_stations

    # ready[u] tracks the earliest time the traveler is ready to board at station u
    ready = [INF] * num_stations
    ready[source] = start_time
    best_target = INF

    # Stations whose ready time decreased in the previous round
    updated_stations = [source]

    # 3. Round-based search (1 round = 1 boarding), amortized O(M + N) total work
    rounds_left = max_boardings
    while rounds_left > 0 and updated_stations:
        rounds_left -= 1

        # Phase A: Board trips from stations whose ready time improved
        boarded_trips = []
        min_board_idx = {}

        for u in updated_stations:
            r_u = ready[u]
            if r_u >= best_target:
                continue

            deps = station_deps[u]
            if not deps:
                continue

            ptr = station_ptr[u]
            n_deps = len(deps)
            if ptr == 0:
                # Jump directly past departures that are even later than needed?
                # No: we WANT all departures >= r_u! Since deps is descending,
                # valid departures form a contiguous slice starting from ptr.
                # Binary search finds the exact cutoff index in O(log(deg(u))).
                end_ptr = bisect_left(station_neg_deps[u], -r_u + 1)
                # Note: -dep < -r_u + 1  <=>  -dep <= -r_u  <=>  dep >= r_u
            else:
                end_ptr = ptr
                while end_ptr < n_deps and deps[end_ptr][0] >= r_u:
                    end_ptr += 1

            while ptr < end_ptr:
                _, t_idx, c_idx = deps[ptr]
                if c_idx < trip_reached[t_idx]:
                    prev = min_board_idx.get(t_idx)
                    if prev is None:
                        min_board_idx[t_idx] = c_idx
                        boarded_trips.append(t_idx)
                    elif c_idx < prev:
                        min_board_idx[t_idx] = c_idx
                ptr += 1

            station_ptr[u] = ptr

        if not boarded_trips:
            break

        # Phase B: Ride boarded trips forward up to previously reached index
        next_updated = []
        in_next_updated = set()

        for t_idx in boarded_trips:
            start_c = min_board_idx[t_idx]
            limit_c = trip_reached[t_idx]
            if start_c >= limit_c:
                continue

            conns = trip_conns[t_idx]
            trip_reached[t_idx] = start_c

            for c_idx in range(start_c, limit_c):
                dep, arr, _, v = conns[c_idx]
                if dep >= best_target:
                    # Subsequent connections in this trip also have dep >= arr > dep >= best_target
                    break

                if v == target and arr < best_target:
                    best_target = arr

                new_ready = arr + transfer[v]
                if new_ready < ready[v] and new_ready < best_target:
                    ready[v] = new_ready
                    if v not in in_next_updated:
                        in_next_updated.add(v)
                        next_updated.append(v)

        updated_stations = next_updated

    return best_target if best_target < INF else None

from collections import deque


def run_kiosk(levels, threshold, patience, arrivals):
    n = len(arrivals)
    for i in range(1, n):
        if arrivals[i][0] < arrivals[i - 1][0]:
            raise ValueError("Arrival times must be non-decreasing")

    if n == 0:
        return []

    # For slot k, offsets[k] = charge_placed - time_placed, so its charge at any
    # time t >= time_placed is min(100, t + offsets[k]).
    offsets = list(levels)
    queue = deque()
    records = []
    idx = 0

    def find_ready_slot(t):
        best_c = threshold - 1
        best_k = -1
        for k, off in enumerate(offsets):
            c = t + off
            if c >= 100:
                return k
            if c > best_c:
                best_c = c
                best_k = k
        return best_k

    while idx < n or queue:
        if not queue:
            t = arrivals[idx][0]
        else:
            t = queue[0][0] + patience
            if idx < n and arrivals[idx][0] < t:
                t = arrivals[idx][0]
            for off in offsets:
                ready_t = threshold - off
                if ready_t < t:
                    t = ready_t

        # 1. Serve the queue
        while queue:
            slot = find_ready_slot(t)
            if slot == -1:
                break
            _, drone, d_charge = queue.popleft()
            offsets[slot] = d_charge - t
            records.append((drone, "SWAP", t, slot))

        # 2. Handle arrivals at time t
        while idx < n and arrivals[idx][0] == t:
            arr_t, drone, d_charge = arrivals[idx]
            idx += 1
            if not queue:
                slot = find_ready_slot(t)
                if slot != -1:
                    offsets[slot] = d_charge - t
                    records.append((drone, "SWAP", t, slot))
                    continue
            queue.append((arr_t, drone, d_charge))

        # 3. Give up
        while queue and queue[0][0] + patience <= t:
            _, drone, _ = queue.popleft()
            records.append((drone, "LEFT", t))

    return records

def simulate_vending(prices, stock, bank, events, timeout):
    prev_t = -1
    for t, _, _ in events:
        if t < prev_t:
            raise ValueError("Event timestamps must be non-decreasing")
        prev_t = t

    cur_stock = dict(stock)
    b5 = bank.get(5, 0)
    b10 = bank.get(10, 0)
    b25 = bank.get(25, 0)
    b100 = bank.get(100, 0)

    escrow = []
    escrow_total = 0
    last_activity = 0
    log = []
    accepted = {5, 10, 25, 100}

    for t, kind, arg in events:
        if escrow and t >= last_activity + timeout:
            escrow.sort(reverse=True)
            log.append(("TIMEOUT", last_activity + timeout, tuple(escrow)))
            escrow.clear()
            escrow_total = 0

        if kind == "coin":
            if arg not in accepted or len(escrow) == 10:
                log.append(("REJECT", t, arg))
            else:
                escrow.append(arg)
                escrow_total += arg
                last_activity = t

        elif kind == "select":
            last_activity = t
            if arg not in prices:
                log.append(("UNKNOWN", t, arg))
            elif cur_stock[arg] == 0:
                log.append(("SOLD_OUT", t, arg))
            elif escrow_total < prices[arg]:
                log.append(("NEED", t, prices[arg] - escrow_total))
            else:
                nb5, nb10, nb25, nb100 = b5, b10, b25, b100
                for c in escrow:
                    if c == 5:
                        nb5 += 1
                    elif c == 10:
                        nb10 += 1
                    elif c == 25:
                        nb25 += 1
                    else:
                        nb100 += 1

                rem = escrow_total - prices[arg]
                k100 = min(nb100, rem // 100)
                rem -= k100 * 100
                k25 = min(nb25, rem // 25)
                rem -= k25 * 25
                k10 = min(nb10, rem // 10)
                rem -= k10 * 10
                k5 = min(nb5, rem // 5)
                rem -= k5 * 5

                if rem == 0:
                    b100 = nb100 - k100
                    b25 = nb25 - k25
                    b10 = nb10 - k10
                    b5 = nb5 - k5
                    cur_stock[arg] -= 1
                    escrow.clear()
                    escrow_total = 0
                    change = (100,) * k100 + (25,) * k25 + (10,) * k10 + (5,) * k5
                    log.append(("VEND", t, arg, change))
                else:
                    log.append(("EXACT_ONLY", t, arg))

        elif kind == "cancel":
            last_activity = t
            if escrow:
                escrow.sort(reverse=True)
                log.append(("RETURN", t, tuple(escrow)))
                escrow.clear()
                escrow_total = 0

    if escrow:
        escrow.sort(reverse=True)
        log.append(("TIMEOUT", last_activity + timeout, tuple(escrow)))
        escrow.clear()
        escrow_total = 0

    return log, (b5, b10, b25, b100)

import re

_NAME_RE = re.compile(r"[a-z0-9_]+", re.ASCII)
_ACTION_WORD_RE = re.compile(r"[a-z]+", re.ASCII)
_ACTION_LIST_RE = re.compile(r"[a-z]+(?:,[a-z]+)*", re.ASCII)
_SEG_RE = re.compile(r"[a-z0-9._-]+", re.ASCII)


class _ResourceMatcher:
    __slots__ = (
        "has_dstar",
        "min_len",
        "exact_segs",
        "dstar_mask",
        "star_mask",
        "lit_masks",
        "accept_bit",
        "init_state",
        "trailing_dstar_bit",
    )

    def __init__(self, raw_segs: tuple[str, ...]) -> None:
        segs: list[str] = []
        for s in raw_segs:
            if s == "**" and segs and segs[-1] == "**":
                continue
            segs.append(s)

        m = len(segs)
        has_dstar = "**" in segs
        self.has_dstar = has_dstar
        self.min_len = sum(1 for s in segs if s != "**")

        if not has_dstar:
            self.exact_segs = tuple(segs)
            self.dstar_mask = 0
            self.star_mask = 0
            self.lit_masks = {}
            self.accept_bit = 0
            self.init_state = 0
            self.trailing_dstar_bit = 0
            return

        self.exact_segs = ()
        dstar_mask = 0
        star_mask = 0
        lit_masks: dict[str, int] = {}
        for idx, s in enumerate(segs):
            bit = 1 << idx
            if s == "**":
                dstar_mask |= bit
            elif s == "*":
                star_mask |= bit
            else:
                lit_masks[s] = lit_masks.get(s, 0) | bit

        self.dstar_mask = dstar_mask
        self.star_mask = star_mask
        self.lit_masks = lit_masks
        self.accept_bit = 1 << m
        init_state = 1 | ((1 & dstar_mask) << 1)
        self.init_state = init_state
        self.trailing_dstar_bit = (1 << (m - 1)) if segs and segs[-1] == "**" else 0

    def matches(self, path_segs: tuple[str, ...]) -> bool:
        n = len(path_segs)
        if not self.has_dstar:
            exact = self.exact_segs
            if n != len(exact):
                return False
            for p, s in zip(exact, path_segs):
                if p != "*" and p != s:
                    return False
            return True

        if n < self.min_len:
            return False

        state = self.init_state
        trailing_bit = self.trailing_dstar_bit
        if trailing_bit and (state & trailing_bit):
            return True

        dstar_mask = self.dstar_mask
        star_mask = self.star_mask
        lit_masks = self.lit_masks

        for s in path_segs:
            state = (((state & (star_mask | lit_masks.get(s, 0))) << 1) | (state & dstar_mask))
            if not state:
                return False
            state |= (state & dstar_mask) << 1
            if trailing_bit and (state & trailing_bit):
                return True

        return bool(state & self.accept_bit)


def _parse_resource(resource: str) -> tuple[str, ...] | None:
    if resource == "/":
        return ()
    if not resource.startswith("/"):
        return None
    segs = resource[1:].split("/")
    for seg in segs:
        if seg != "*" and seg != "**" and not _SEG_RE.fullmatch(seg):
            return None
    return tuple(segs)


def _parse_path(path: str) -> tuple[str, ...] | None:
    if path == "/":
        return ()
    if not path.startswith("/"):
        return None
    segs = path[1:].split("/")
    for seg in segs:
        if not _SEG_RE.fullmatch(seg):
            return None
    return tuple(segs)


def evaluate_access(rules, requests) -> list[str]:
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")
    if not isinstance(requests, list):
        raise TypeError("requests must be a list")

    matcher_pool: dict[str, tuple[int, _ResourceMatcher]] = {}
    parsed_rules = []

    for i, rule in enumerate(rules):
        if not isinstance(rule, str):
            raise TypeError(f"rule {i}: not a str")
        fields = rule.split()
        if len(fields) != 4:
            raise ValueError(f"rule {i}: expected 4 fields, got {len(fields)}")
        effect, principal, action, resource = fields

        if effect not in ("ALLOW", "DENY"):
            raise ValueError(f"rule {i}: bad effect {effect!r}")

        if principal == "*":
            p_spec = 0
            p_val = None
        elif principal.startswith("user:") and _NAME_RE.fullmatch(principal[5:]):
            p_spec = 2
            p_val = principal[5:]
        elif principal.startswith("group:") and _NAME_RE.fullmatch(principal[6:]):
            p_spec = 1
            p_val = principal[6:]
        else:
            raise ValueError(f"rule {i}: bad principal {principal!r}")

        if action == "*":
            a_spec = 0
            actions = None
        elif _ACTION_LIST_RE.fullmatch(action):
            a_spec = 1
            actions = frozenset(action.split(","))
        else:
            raise ValueError(f"rule {i}: bad action {action!r}")

        raw_segs = _parse_resource(resource)
        if raw_segs is None:
            raise ValueError(f"rule {i}: bad resource {resource!r}")

        l_spec = sum(1 for seg in raw_segs if seg != "*" and seg != "**")
        entry = matcher_pool.get(resource)
        if entry is None:
            entry = (len(matcher_pool), _ResourceMatcher(raw_segs))
            matcher_pool[resource] = entry
        pat_id, matcher = entry

        sort_key = (-l_spec, -p_spec, -a_spec, 0 if effect == "DENY" else 1, i)
        decision = f"{effect} by rule {i}"
        parsed_rules.append((sort_key, p_spec, p_val, actions, pat_id, matcher, decision))

    parsed_requests = []
    for j, req in enumerate(requests):
        if not isinstance(req, tuple) or len(req) != 4:
            raise TypeError(f"request {j}: expected 4-tuple")
        user, groups, action, path = req

        if not isinstance(user, str) or not _NAME_RE.fullmatch(user):
            raise ValueError(f"request {j}: bad user {user!r}")
        if not isinstance(groups, list) or not all(
            isinstance(g, str) and _NAME_RE.fullmatch(g) for g in groups
        ):
            raise ValueError(f"request {j}: bad groups")
        if not isinstance(action, str) or not _ACTION_WORD_RE.fullmatch(action):
            raise ValueError(f"request {j}: bad action {action!r}")
        if not isinstance(path, str):
            raise ValueError(f"request {j}: bad path {path!r}")
        path_segs = _parse_path(path)
        if path_segs is None:
            raise ValueError(f"request {j}: bad path {path!r}")

        parsed_requests.append((user, frozenset(groups), action, path_segs))

    # Sorting by (-L, -P, -A, DENY-before-ALLOW, rule_index) ensures that the
    # first matching rule has maximal specificity and respects DENY precedence
    # and smallest rule index tie-breaking.
    parsed_rules.sort(key=lambda r: r[0])

    decisions: list[str] = []
    for user, groups_set, action, path_segs in parsed_requests:
        pat_cache: dict[int, bool] = {}
        verdict = "DENY by default"
        for _, p_spec, p_val, actions, pat_id, matcher, decision in parsed_rules:
            if p_spec == 2 and p_val != user:
                continue
            if p_spec == 1 and p_val not in groups_set:
                continue
            if actions is not None and action not in actions:
                continue

            res_match = pat_cache.get(pat_id)
            if res_match is None:
                res_match = matcher.matches(path_segs)
                pat_cache[pat_id] = res_match
            if res_match:
                verdict = decision
                break

        decisions.append(verdict)

    return decisions

import copy
import json
import re

_IDENT_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$", re.ASCII)


def _get_type(v) -> str:
    """Return the JSON-like type name of v."""
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "bool"
    if isinstance(v, int):
        return "int"
    if isinstance(v, float):
        return "float"
    if isinstance(v, str):
        return "str"
    if isinstance(v, list):
        return "list"
    if isinstance(v, dict):
        return "dict"
    return type(v).__name__


def _format_path(parent_path: str, name: str) -> str:
    """Format the nested JSONPath-style string for `name` inside `parent_path`."""
    if _IDENT_RE.fullmatch(name):
        return f"{parent_path}.{name}"
    return f"{parent_path}[{json.dumps(name, ensure_ascii=False)}]"


def merge_layers(layers) -> tuple[dict, list[str]]:
    if not isinstance(layers, list):
        raise TypeError("layers must be a list")

    result: dict = {}
    warnings: list[str] = []

    def _merge_dict(target: dict, overlay: dict, path: str, layer_idx: int) -> None:
        for k, v in overlay.items():
            if not isinstance(k, str):
                raise TypeError(f"layer {layer_idx}: non-string key at {path}")

            if k.startswith("-"):
                directive = "DELETE"
                name = k[1:]
            elif k.endswith("+"):
                directive = "APPEND"
                name = k[:-1]
            else:
                directive = "SET"
                name = k

            if name == "":
                raise ValueError(f"layer {layer_idx}: empty key name at {path}")

            q = _format_path(path, name)

            if directive == "DELETE":
                if v is not None:
                    raise ValueError(f"layer {layer_idx}: delete directive needs null at {q}")
                if name in target:
                    del target[name]
                else:
                    warnings.append(f"layer {layer_idx}: delete of missing key at {q}")

            elif directive == "APPEND":
                if not isinstance(v, list):
                    raise ValueError(f"layer {layer_idx}: append directive needs a list at {q}")
                if name not in target:
                    target[name] = copy.deepcopy(v)
                elif isinstance(target[name], list):
                    target[name].extend(copy.deepcopy(elem) for elem in v)
                else:
                    t_type = _get_type(target[name])
                    raise ValueError(f"layer {layer_idx}: cannot append to {t_type} at {q}")

            else:  # SET
                if name in target:
                    old_type = _get_type(target[name])
                    new_type = _get_type(v)
                    if old_type != new_type:
                        warnings.append(
                            f"layer {layer_idx}: type change at {q}: {old_type} -> {new_type}"
                        )

                if isinstance(v, dict):
                    if not (name in target and isinstance(target[name], dict)):
                        target[name] = {}
                    _merge_dict(target[name], v, q, layer_idx)
                else:
                    target[name] = copy.deepcopy(v)

    for layer_idx, layer in enumerate(layers):
        if not isinstance(layer, dict):
            raise TypeError(f"layer {layer_idx} is not a dict")
        _merge_dict(result, layer, "$", layer_idx)

    return result, warnings

import datetime
import re

_OPENING_RE = re.compile(r"-?(0|[1-9][0-9]{0,8})\.[0-9]{2}")
_DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")
_AMOUNT_RE = re.compile(r"(0|[1-9][0-9]{0,8})(\.[0-9]{1,2})?")
_VALID_KINDS = ("credit", "debit", "fee")


def _parse_cents(amount_str: str) -> int:
    neg = amount_str.startswith("-")
    if neg:
        amount_str = amount_str[1:]
    if "." in amount_str:
        whole, frac = amount_str.split(".")
        frac = frac.ljust(2, "0")
    else:
        whole, frac = amount_str, "00"
    cents = int(whole) * 100 + int(frac)
    return -cents if neg and cents != 0 else cents


def _format_money(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    abs_cents = abs(cents)
    whole, frac = divmod(abs_cents, 100)
    return f"{sign}{whole:,}.{frac:02d}"


def _format_memo(memo: str) -> str:
    normalized = " ".join(memo.split())
    if len(normalized) > 20:
        normalized = normalized[:19] + "~"
    return normalized.ljust(20)


def render_statement(opening, entries) -> list[str]:
    # 1-3: Top-level validation
    if not isinstance(opening, str):
        raise TypeError("opening must be a str")
    if _OPENING_RE.fullmatch(opening) is None:
        raise ValueError("opening: bad amount " + repr(opening))
    if not isinstance(entries, list):
        raise TypeError("entries must be a list")

    # 4: Per-entry validation
    parsed_entries: list[tuple[str, str, int, str]] = []
    prev_date: str | None = None

    for i, entry in enumerate(entries):
        if not isinstance(entry, tuple) or len(entry) != 4:
            raise TypeError(f"entry {i}: expected 4-tuple")

        date, kind, amount, memo = entry

        # b. date check
        if not isinstance(date, str):
            raise ValueError(f"entry {i}: bad date {date!r}")
        m_date = _DATE_RE.fullmatch(date)
        if m_date is None:
            raise ValueError(f"entry {i}: bad date {date!r}")
        year, month, day = map(int, m_date.groups())
        if not (1900 <= year <= 2999):
            raise ValueError(f"entry {i}: bad date {date!r}")
        try:
            datetime.date(year, month, day)
        except ValueError:
            raise ValueError(f"entry {i}: bad date {date!r}") from None

        # c. date ordering check
        if prev_date is not None and date < prev_date:
            raise ValueError(f"entry {i}: date out of order")
        prev_date = date

        # d. kind check
        if not isinstance(kind, str) or kind not in _VALID_KINDS:
            raise ValueError(f"entry {i}: bad kind {kind!r}")

        # e. amount check
        if not isinstance(amount, str) or _AMOUNT_RE.fullmatch(amount) is None:
            raise ValueError(f"entry {i}: bad amount {amount!r}")
        amount_cents = _parse_cents(amount)
        if amount_cents == 0:
            raise ValueError(f"entry {i}: bad amount {amount!r}")

        # f. memo check
        if (
            not isinstance(memo, str)
            or not memo.split()
            or any(ord(ch) < 32 or ord(ch) == 127 for ch in memo)
        ):
            raise ValueError(f"entry {i}: bad memo")

        parsed_entries.append((date, kind, amount_cents, memo))

    # Processing & rendering
    balance = _parse_cents(opening)
    lines = [f"Opening balance: {_format_money(balance)}"]

    counts = {"credit": 0, "debit": 0, "fee": 0}
    auto_fee_dates: set[str] = set()

    def apply_and_render(date: str, kind: str, amount_cents: int, memo: str) -> None:
        nonlocal balance
        if kind == "credit":
            balance += amount_cents
            sign_prefix = "+"
        else:
            balance -= amount_cents
            sign_prefix = "-"

        counts[kind] += 1
        memo_col = _format_memo(memo)
        amt_col = f"{sign_prefix}{_format_money(amount_cents)}".rjust(14)
        bal_col = _format_money(balance).rjust(15)
        flag = " OD" if balance < 0 else ""
        lines.append(f"{date}  {memo_col}  {amt_col}  {bal_col}{flag}")

    for date, kind, amount_cents, memo in parsed_entries:
        apply_and_render(date, kind, amount_cents, memo)
        if kind == "debit" and balance < 0 and date not in auto_fee_dates:
            auto_fee_dates.add(date)
            apply_and_render(date, "fee", 2500, "OVERDRAFT FEE")

    lines.append(f"Closing balance: {_format_money(balance)}")
    lines.append(
        f"Credits: {counts['credit']}  Debits: {counts['debit']}  Fees: {counts['fee']}"
    )
    return lines

import operator
import re

_NUM = r"(?:0|[1-9][0-9]*)"
_RC_NUM = r"(?:[1-9][0-9]*)"

_VERSION_RE = re.compile(rf"\A({_NUM})\.({_NUM})\.({_NUM})(?:~rc({_RC_NUM}))?\Z")
_OP_VERSION_RE = re.compile(
    rf"\A(>=|<=|!=|=|>|<)?({_NUM})\.({_NUM})\.({_NUM})(?:~rc({_RC_NUM}))?\Z"
)
_MAJOR_WILD_RE = re.compile(rf"\A({_NUM})\.\*\Z")
_MINOR_WILD_RE = re.compile(rf"\A({_NUM})\.({_NUM})\.\*\Z")
_AT_RE = re.compile(rf"\A@({_NUM})\.({_NUM})\Z")

_OPS = {
    None: operator.eq,
    "=": operator.eq,
    "!=": operator.ne,
    ">": operator.gt,
    ">=": operator.ge,
    "<": operator.lt,
    "<=": operator.le,
}

# Parsed version tuple: (major, minor, patch, is_final, rc_num)
# Release candidates have is_final == 0 and rc_num >= 1;
# plain releases have is_final == 1 and rc_num == 0.
_ParsedVersion = tuple[int, int, int, int, int]


def _parse_version(text: str) -> _ParsedVersion | None:
    m = _VERSION_RE.fullmatch(text)
    if m is None:
        return None
    major, minor, patch, rc = m.groups()
    if rc is None:
        return (int(major), int(minor), int(patch), 1, 0)
    return (int(major), int(minor), int(patch), 0, int(rc))


def _parse_clause(clause: str):
    if clause == "*":
        return lambda v: True

    m = _OP_VERSION_RE.fullmatch(clause)
    if m is not None:
        op_str, major, minor, patch, rc = m.groups()
        target = (
            (int(major), int(minor), int(patch), 1, 0)
            if rc is None
            else (int(major), int(minor), int(patch), 0, int(rc))
        )
        op_fn = _OPS[op_str]
        return lambda v, op_fn=op_fn, target=target: op_fn(v, target)

    m = _MAJOR_WILD_RE.fullmatch(clause)
    if m is not None:
        major = int(m.group(1))
        return lambda v, major=major: v[0] == major

    m = _MINOR_WILD_RE.fullmatch(clause)
    if m is not None:
        major = int(m.group(1))
        minor = int(m.group(2))
        return lambda v, major=major, minor=minor: v[0] == major and v[1] == minor

    m = _AT_RE.fullmatch(clause)
    if m is not None:
        major = int(m.group(1))
        minor = int(m.group(2))
        return lambda v, major=major, minor=minor: v[0] == major and v[1] >= minor

    return None


def pick_version(available, constraint) -> str | None:
    if not isinstance(available, list):
        raise TypeError("available must be a list")

    parsed_available: list[tuple[_ParsedVersion, str]] = []
    for i, element in enumerate(available):
        if not isinstance(element, str):
            raise ValueError(f"invalid version at index {i}: {element!r}")
        parsed = _parse_version(element)
        if parsed is None:
            raise ValueError(f"invalid version at index {i}: {element!r}")
        parsed_available.append((parsed, element))

    if not isinstance(constraint, str):
        raise TypeError("constraint must be a str")

    if constraint.strip(" ") == "":
        raise ValueError("empty constraint")

    alternatives = []
    for a, raw_alt in enumerate(constraint.split("|"), start=1):
        alt = raw_alt.strip(" ")
        allows_rc = False
        if alt.startswith("?"):
            allows_rc = True
            alt = alt[1:].strip(" ")
        if alt == "":
            raise ValueError(f"alternative {a} is empty")

        predicates = []
        for c, raw_clause in enumerate(alt.split(","), start=1):
            clause = raw_clause.strip(" ")
            pred = _parse_clause(clause)
            if pred is None:
                raise ValueError(
                    f"alternative {a}, clause {c}: invalid clause {clause!r}"
                )
            predicates.append(pred)

        alternatives.append((allows_rc, predicates))

    best_parsed: _ParsedVersion | None = None
    best_str: str | None = None

    for ver, ver_str in parsed_available:
        is_rc = ver[3] == 0
        if any(
            (not is_rc or allows_rc) and all(pred(ver) for pred in predicates)
            for allows_rc, predicates in alternatives
        ):
            if best_parsed is None or ver > best_parsed:
                best_parsed = ver
                best_str = ver_str

    return best_str

import re

_KEY_MATCH = re.compile(r"[A-Za-z_][A-Za-z0-9_-]*\Z", re.ASCII).match
_INT_MATCH = re.compile(r"-?(?:0|[1-9][0-9]*)\Z", re.ASCII).match
_QUOTE_SPECIAL_SEARCH = re.compile(r'["\\]').search
_ESCAPES = {"\\": "\\", '"': '"', "n": "\n", "t": "\t"}


def _parse_int(s: str) -> int:
    if len(s) <= 600:
        return int(s)
    neg = s[0] == "-"
    start = 1 if neg else 0
    val = 0
    for i in range(start, len(s), 600):
        chunk = s[i : i + 600]
        val = val * (10 ** len(chunk)) + int(chunk)
    return -val if neg else val


def parse_outline(text: str) -> tuple:
    key_match = _KEY_MATCH
    int_match = _INT_MATCH
    quote_search = _QUOTE_SPECIAL_SEARCH
    escapes = _ESCAPES

    root = None
    # Each entry: (indent, kind, container), where kind is 0 for dict, 1 for list.
    stack = []
    # Either None or (opener_indent, container, key_or_index).
    pending_opener = None

    for lineno, line in enumerate(text.split("\n"), 1):
        rest = line.lstrip(" \t")
        if not rest or rest[0] == "#":
            continue

        indent = len(line) - len(rest)
        if "\t" in line[:indent]:
            return ("error", lineno, "tab in indentation")

        # 2 & 3. Entry syntax (ITEM vs KEY)
        if rest == "-" or rest.startswith("- "):
            line_kind = 1
            key = None
            scalar_text = rest[2:].strip(" ")
            is_opener = scalar_text == ""
        else:
            colon = rest.find(":")
            if colon <= 0:
                return ("error", lineno, "invalid entry")
            key = rest[:colon]
            if key_match(key) is None:
                return ("error", lineno, "invalid entry")
            after = rest[colon + 1 :]
            if not after:
                is_opener = True
                scalar_text = ""
            elif after[0] == " ":
                scalar_text = after.strip(" ")
                is_opener = scalar_text == ""
            else:
                return ("error", lineno, "invalid entry")
            line_kind = 0

        # 4. Scalar conversion
        if is_opener:
            val = None
        elif scalar_text[0] == '"':
            if "\\" not in scalar_text:
                q = scalar_text.find('"', 1)
                if q != len(scalar_text) - 1 or q < 1:
                    return ("error", lineno, "bad string")
                val = scalar_text[1:-1]
            else:
                parts = []
                pos = 1
                n = len(scalar_text)
                closed = False
                while pos < n:
                    m = quote_search(scalar_text, pos)
                    if m is None:
                        break
                    idx = m.start()
                    if idx > pos:
                        parts.append(scalar_text[pos:idx])
                    if scalar_text[idx] == '"':
                        if idx != n - 1:
                            return ("error", lineno, "bad string")
                        closed = True
                        break
                    if idx + 1 >= n:
                        return ("error", lineno, "bad escape")
                    esc = escapes.get(scalar_text[idx + 1])
                    if esc is None:
                        return ("error", lineno, "bad escape")
                    parts.append(esc)
                    pos = idx + 2
                if not closed:
                    return ("error", lineno, "bad string")
                val = "".join(parts)
        elif scalar_text == "true":
            val = True
        elif scalar_text == "false":
            val = False
        elif scalar_text == "null":
            val = None
        elif int_match(scalar_text) is not None:
            val = _parse_int(scalar_text)
        else:
            val = scalar_text

        # Structure checks
        if not stack:
            if indent != 0:
                return ("error", lineno, "unexpected indent")
            container = {} if line_kind == 0 else []
            root = container
            stack.append((0, line_kind, container))
        elif pending_opener is not None and indent > pending_opener[0]:
            container = {} if line_kind == 0 else []
            _, p_cont, p_ref = pending_opener
            p_cont[p_ref] = container
            stack.append((indent, line_kind, container))
        else:
            pending_opener = None
            top_indent = stack[-1][0]
            if indent > top_indent:
                return ("error", lineno, "unexpected indent")
            if indent < top_indent:
                while stack[-1][0] > indent:
                    stack.pop()
                if stack[-1][0] != indent:
                    return ("error", lineno, "inconsistent dedent")
            _, block_kind, container = stack[-1]
            if line_kind != block_kind:
                return ("error", lineno, "mixed block")
            if line_kind == 0 and key in container:
                return ("error", lineno, f"duplicate key '{key}'")

        # Insert entry into target block
        if line_kind == 0:
            container[key] = val
            pending_opener = (indent, container, key) if is_opener else None
        else:
            if is_opener:
                pending_opener = (indent, container, len(container))
            else:
                pending_opener = None
            container.append(val)

    return ("ok", root)

import re

_TOKEN_RE = re.compile(r"\[|\]|[^ \t\n\r\[\]]+")
_INT_RE = re.compile(r"-?[0-9]+\Z", re.ASCII)

# Opcodes <= 0 are internal control instructions (consume no steps).
# Opcodes > 0 correspond 1-to-1 with executable elements (consume 1 step each).
_OP_HALT = -1
_OP_RET = 0
_OP_INT = 1
_OP_QUOT = 2
_OP_WORD = 3
_OP_DUP = 4
_OP_DROP = 5
_OP_SWAP = 6
_OP_OVER = 7
_OP_ROT = 8
_OP_ADD = 9
_OP_SUB = 10
_OP_MUL = 11
_OP_DIV = 12
_OP_MOD = 13
_OP_LT = 14
_OP_EQ = 15
_OP_IF = 16
_OP_CALL = 17
_OP_DIP = 18
_OP_TIMES = 19
_OP_WHILE = 20
_OP_DEF = 21
_OP_UNKNOWN = 22

_BUILTIN_OPS = {
    "dup": _OP_DUP,
    "drop": _OP_DROP,
    "swap": _OP_SWAP,
    "over": _OP_OVER,
    "rot": _OP_ROT,
    "+": _OP_ADD,
    "-": _OP_SUB,
    "*": _OP_MUL,
    "/": _OP_DIV,
    "%": _OP_MOD,
    "<": _OP_LT,
    "=": _OP_EQ,
    "if": _OP_IF,
    "call": _OP_CALL,
    "dip": _OP_DIP,
    "times": _OP_TIMES,
    "while": _OP_WHILE,
}

_FORBIDDEN_NAMES = frozenset(_BUILTIN_OPS) | {"[", "]", ":", ";"}

# Negative continuation tags on cstack (return PCs are >= 0).
_RET_DIP = -1
_RET_TIMES = -2
_RET_WHILE_COND = -3
_RET_WHILE_BODY = -4


def _parse_big_int(tok: str) -> int:
    neg = tok[0] == "-"
    i = 1 if neg else 0
    val = 0
    n = len(tok)
    while i < n:
        chunk = tok[i : i + 4000]
        val = val * (10 ** len(chunk)) + int(chunk)
        i += 4000
    return -val if neg else val


def run_pile(src: str, max_steps: int) -> tuple:
    tokens = _TOKEN_RE.findall(src)
    n = len(tokens)

    # 1. Structure check (also records matching close indexes and defined word IDs)
    match_close = [0] * n
    open_stack = []  # (is_colon, token_idx)
    word_map = {}
    int_match = _INT_RE.match
    forbidden = _FORBIDDEN_NAMES

    i = 0
    while i < n:
        tok = tokens[i]
        if tok == "[":
            open_stack.append((False, i))
            i += 1
        elif tok == "]":
            if not open_stack or open_stack[-1][0]:
                return ("error", i, "unmatched ]")
            _, open_idx = open_stack.pop()
            match_close[open_idx] = i
            i += 1
        elif tok == ":":
            if open_stack:
                return ("error", i, "misplaced :")
            if i + 1 >= n:
                return ("error", i, "unclosed :")
            name = tokens[i + 1]
            if name in forbidden or int_match(name) is not None:
                return ("error", i + 1, "bad name")
            if name not in word_map:
                word_map[name] = len(word_map)
            open_stack.append((True, i))
            i += 2
        elif tok == ";":
            if not open_stack or not open_stack[-1][0]:
                return ("error", i, "unmatched ;")
            _, open_idx = open_stack.pop()
            match_close[open_idx] = i
            i += 1
        else:
            i += 1

    if open_stack:
        is_colon, open_idx = open_stack[0]
        return ("error", open_idx, "unclosed :" if is_colon else "unclosed [")

    # 2. Compile tokens 1-to-1 into flat arrays so pc == token_index everywhere
    ops = [0] * (n + 1)  # 0 is _OP_RET (used for ']' and ';')
    args = [None] * (n + 1)
    ops[n] = _OP_HALT

    builtin_get = _BUILTIN_OPS.get
    word_get = word_map.get

    i = 0
    while i < n:
        tok = tokens[i]
        b_op = builtin_get(tok)
        if b_op is not None:
            ops[i] = b_op
            i += 1
        elif tok == "[":
            close_i = match_close[i]
            ops[i] = _OP_QUOT
            args[i] = (i + 1, close_i)
            i += 1
        elif tok == "]" or tok == ";":
            i += 1
        elif tok == ":":
            close_i = match_close[i]
            ops[i] = _OP_DEF
            args[i] = (word_map[tokens[i + 1]], close_i + 1)
            i += 2
        elif int_match(tok) is not None:
            ops[i] = _OP_INT
            args[i] = int(tok) if len(tok) <= 4000 else _parse_big_int(tok)
            i += 1
        else:
            wid = word_get(tok)
            if wid is not None:
                ops[i] = _OP_WORD
                args[i] = wid
            else:
                ops[i] = _OP_UNKNOWN
            i += 1

    # 3. Execute flat bytecode iteratively
    stack = []
    defs = [-1] * len(word_map)
    cstack = []
    dip_stack = []
    times_q = []
    times_rem = []
    while_c = []
    while_b = []
    while_tok = []

    int_type = int
    tuple_type = tuple
    pc = 0
    steps = 0

    while True:
        op = ops[pc]
        if op <= 0:
            if op == 0:  # _OP_RET
                while True:
                    ret = cstack.pop()
                    if ret >= 0:
                        pc = ret
                        break
                    if ret == _RET_DIP:
                        stack.append(dip_stack.pop())
                        continue
                    if ret == _RET_TIMES:
                        rem = times_rem[-1] - 1
                        if rem > 0:
                            times_rem[-1] = rem
                            cstack.append(_RET_TIMES)
                            pc = times_q[-1]
                        else:
                            times_rem.pop()
                            pc = times_q.pop()
                        break
                    if ret == _RET_WHILE_COND:
                        if not stack:
                            return ("error", while_tok[-1], "stack underflow")
                        v = stack.pop()
                        if type(v) is not int_type:
                            return ("error", while_tok[-1], "type error")
                        if v:
                            cstack.append(_RET_WHILE_BODY)
                            pc = while_b[-1]
                            break
                        while_c.pop()
                        while_b.pop()
                        while_tok.pop()
                        continue
                    # _RET_WHILE_BODY
                    cstack.append(_RET_WHILE_COND)
                    pc = while_c[-1]
                    break
                continue
            break  # _OP_HALT

        steps += 1
        if steps > max_steps:
            return ("error", pc, "step limit exceeded")

        if op <= 11:
            if op <= 5:
                if op == _OP_INT:
                    stack.append(args[pc])
                    pc += 1
                elif op == _OP_QUOT:
                    q = args[pc]
                    stack.append(q)
                    pc = q[1] + 1
                elif op == _OP_WORD:
                    body = defs[args[pc]]
                    if body < 0:
                        return ("error", pc, f"unknown word '{tokens[pc]}'")
                    if ops[pc + 1]:
                        cstack.append(pc + 1)
                    pc = body
                elif op == _OP_DUP:
                    if not stack:
                        return ("error", pc, "stack underflow")
                    stack.append(stack[-1])
                    pc += 1
                else:  # _OP_DROP
                    if not stack:
                        return ("error", pc, "stack underflow")
                    stack.pop()
                    pc += 1
            else:
                if op == _OP_SWAP:
                    if len(stack) < 2:
                        return ("error", pc, "stack underflow")
                    stack[-1], stack[-2] = stack[-2], stack[-1]
                    pc += 1
                elif op == _OP_OVER:
                    if len(stack) < 2:
                        return ("error", pc, "stack underflow")
                    stack.append(stack[-2])
                    pc += 1
                elif op == _OP_ROT:
                    if len(stack) < 3:
                        return ("error", pc, "stack underflow")
                    stack[-3], stack[-2], stack[-1] = stack[-2], stack[-1], stack[-3]
                    pc += 1
                elif op == _OP_ADD:
                    if len(stack) < 2:
                        return ("error", pc, "stack underflow")
                    b = stack[-1]
                    a = stack[-2]
                    if type(a) is not int_type or type(b) is not int_type:
                        return ("error", pc, "type error")
                    stack.pop()
                    stack[-1] = a + b
                    pc += 1
                elif op == _OP_SUB:
                    if len(stack) < 2:
                        return ("error", pc, "stack underflow")
                    b = stack[-1]
                    a = stack[-2]
                    if type(a) is not int_type or type(b) is not int_type:
                        return ("error", pc, "type error")
                    stack.pop()
                    stack[-1] = a - b
                    pc += 1
                else:  # _OP_MUL
                    if len(stack) < 2:
                        return ("error", pc, "stack underflow")
                    b = stack[-1]
                    a = stack[-2]
                    if type(a) is not int_type or type(b) is not int_type:
                        return ("error", pc, "type error")
                    stack.pop()
                    stack[-1] = a * b
                    pc += 1
        else:
            if op <= 17:
                if op == _OP_DIV:
                    if len(stack) < 2:
                        return ("error", pc, "stack underflow")
                    b = stack[-1]
                    a = stack[-2]
                    if type(a) is not int_type or type(b) is not int_type:
                        return ("error", pc, "type error")
                    if b == 0:
                        return ("error", pc, "division by zero")
                    stack.pop()
                    stack[-1] = a // b
                    pc += 1
                elif op == _OP_MOD:
                    if len(stack) < 2:
                        return ("error", pc, "stack underflow")
                    b = stack[-1]
                    a = stack[-2]
                    if type(a) is not int_type or type(b) is not int_type:
                        return ("error", pc, "type error")
                    if b == 0:
                        return ("error", pc, "division by zero")
                    stack.pop()
                    stack[-1] = a % b
                    pc += 1
                elif op == _OP_LT:
                    if len(stack) < 2:
                        return ("error", pc, "stack underflow")
                    b = stack[-1]
                    a = stack[-2]
                    if type(a) is not int_type or type(b) is not int_type:
                        return ("error", pc, "type error")
                    stack.pop()
                    stack[-1] = 1 if a < b else 0
                    pc += 1
                elif op == _OP_EQ:
                    if len(stack) < 2:
                        return ("error", pc, "stack underflow")
                    b = stack[-1]
                    a = stack[-2]
                    if type(a) is not int_type or type(b) is not int_type:
                        return ("error", pc, "type error")
                    stack.pop()
                    stack[-1] = 1 if a == b else 0
                    pc += 1
                elif op == _OP_IF:
                    if len(stack) < 3:
                        return ("error", pc, "stack underflow")
                    f = stack[-1]
                    t = stack[-2]
                    c = stack[-3]
                    if (
                        type(c) is not int_type
                        or type(t) is not tuple_type
                        or type(f) is not tuple_type
                    ):
                        return ("error", pc, "type error")
                    stack.pop()
                    stack.pop()
                    stack.pop()
                    q = t if c else f
                    if q[0] == q[1]:
                        pc += 1
                    else:
                        if ops[pc + 1]:
                            cstack.append(pc + 1)
                        pc = q[0]
                else:  # _OP_CALL
                    if not stack:
                        return ("error", pc, "stack underflow")
                    q = stack[-1]
                    if type(q) is not tuple_type:
                        return ("error", pc, "type error")
                    stack.pop()
                    if q[0] == q[1]:
                        pc += 1
                    else:
                        if ops[pc + 1]:
                            cstack.append(pc + 1)
                        pc = q[0]
            else:
                if op == _OP_DIP:
                    if len(stack) < 2:
                        return ("error", pc, "stack underflow")
                    q = stack[-1]
                    if type(q) is not tuple_type:
                        return ("error", pc, "type error")
                    stack.pop()
                    if q[0] == q[1]:
                        pc += 1
                    else:
                        a = stack.pop()
                        if ops[pc + 1]:
                            cstack.append(pc + 1)
                        dip_stack.append(a)
                        cstack.append(_RET_DIP)
                        pc = q[0]
                elif op == _OP_TIMES:
                    if len(stack) < 2:
                        return ("error", pc, "stack underflow")
                    cnt = stack[-1]
                    q = stack[-2]
                    if type(q) is not tuple_type or type(cnt) is not int_type:
                        return ("error", pc, "type error")
                    if cnt < 0:
                        return ("error", pc, "negative count")
                    stack.pop()
                    stack.pop()
                    if cnt == 0 or q[0] == q[1]:
                        pc += 1
                    else:
                        if ops[pc + 1]:
                            cstack.append(pc + 1)
                        if cnt > 1:
                            times_q.append(q[0])
                            times_rem.append(cnt - 1)
                            cstack.append(_RET_TIMES)
                        pc = q[0]
                elif op == _OP_WHILE:
                    if len(stack) < 2:
                        return ("error", pc, "stack underflow")
                    b = stack[-1]
                    c = stack[-2]
                    if type(c) is not tuple_type or type(b) is not tuple_type:
                        return ("error", pc, "type error")
                    stack.pop()
                    stack.pop()
                    if ops[pc + 1]:
                        cstack.append(pc + 1)
                    while_c.append(c[0])
                    while_b.append(b[0])
                    while_tok.append(pc)
                    cstack.append(_RET_WHILE_COND)
                    pc = c[0]
                elif op == _OP_DEF:
                    wid, next_pc = args[pc]
                    defs[wid] = pc + 2
                    pc = next_pc
                else:  # _OP_UNKNOWN
                    return ("error", pc, f"unknown word '{tokens[pc]}'")

    # 4. Format resulting stack iteratively
    quot_memo = {}

    def format_quot(b_start: int, b_end: int) -> list:
        cached = quot_memo.get(b_start)
        if cached is not None:
            return cached
        root = []
        lst_stack = [root]
        start_stack = [b_start]
        cur = root
        k = b_start
        while k < b_end:
            t = tokens[k]
            if t == "[":
                sub_start = k + 1
                sub_cached = quot_memo.get(sub_start)
                if sub_cached is not None:
                    cur.append(sub_cached)
                    k = match_close[k] + 1
                else:
                    sub = []
                    cur.append(sub)
                    lst_stack.append(sub)
                    start_stack.append(sub_start)
                    cur = sub
                    k = sub_start
            elif t == "]":
                quot_memo[start_stack.pop()] = cur
                lst_stack.pop()
                cur = lst_stack[-1]
                k += 1
            else:
                cur.append(t)
                k += 1
        quot_memo[b_start] = root
        return root

    result = [v if type(v) is int_type else format_quot(v[0], v[1]) for v in stack]
    return ("ok", result)

_MISSING = object()

_OP_NOT = 0
_OP_AND = 1
_OP_OR = 2
_OP_HAS = 3
_OP_EQ = 4
_OP_NE = 5
_OP_LT = 6
_OP_LE = 7
_OP_GT = 8
_OP_GE = 9
_OP_IN = 10

_KEYWORDS = {
    "and": "AND",
    "or": "OR",
    "not": "NOT",
    "in": "IN",
    "has": "HAS",
}

_PUNCT = {
    "(": "LPAREN",
    ")": "RPAREN",
    "[": "LBRACK",
    "]": "RBRACK",
    ",": "COMMA",
}

_CMP_OPCODES = {
    "=": _OP_EQ,
    "!=": _OP_NE,
    "<": _OP_LT,
    "<=": _OP_LE,
    ">": _OP_GT,
    ">=": _OP_GE,
}

_CHUNK_SIZE = 4000
_CHUNK_BASE = 10**_CHUNK_SIZE


def _parse_int(raw: str) -> int:
    if len(raw) <= _CHUNK_SIZE:
        return int(raw)
    neg = raw[0] == "-"
    start = 1 if neg else 0
    val = 0
    n = len(raw)
    for pos in range(start, n, _CHUNK_SIZE):
        chunk = raw[pos : pos + _CHUNK_SIZE]
        if len(chunk) == _CHUNK_SIZE:
            val = val * _CHUNK_BASE + int(chunk)
        else:
            val = val * (10 ** len(chunk)) + int(chunk)
    return -val if neg else val


def _lex(query: str):
    tokens = []
    n = len(query)
    i = 0
    while i < n:
        c = query[i]
        if c == " " or c == "\t" or c == "\n":
            i += 1
            continue

        if c in _PUNCT:
            tokens.append((_PUNCT[c], i, c, None))
            i += 1
            continue

        if c == "!":
            if i + 1 < n and query[i + 1] == "=":
                tokens.append(("CMP", i, "!=", "!="))
                i += 2
                continue
            return None, ("error", i, "unexpected character '!'")

        if c == "<":
            if i + 1 < n and query[i + 1] == "=":
                tokens.append(("CMP", i, "<=", "<="))
                i += 2
            else:
                tokens.append(("CMP", i, "<", "<"))
                i += 1
            continue

        if c == ">":
            if i + 1 < n and query[i + 1] == "=":
                tokens.append(("CMP", i, ">=", ">="))
                i += 2
            else:
                tokens.append(("CMP", i, ">", ">"))
                i += 1
            continue

        if c == "=":
            tokens.append(("CMP", i, "=", "="))
            i += 1
            continue

        if ("0" <= c <= "9") or (c == "-" and i + 1 < n and "0" <= query[i + 1] <= "9"):
            start = i
            i += 2 if c == "-" else 1
            while i < n and "0" <= query[i] <= "9":
                i += 1
            raw = query[start:i]
            tokens.append(("INT", start, raw, _parse_int(raw)))
            continue

        if c == '"':
            start = i
            i += 1
            chars = []
            closed = False
            while i < n:
                ch = query[i]
                if ch == '"':
                    i += 1
                    closed = True
                    break
                if ch == "\\":
                    if i + 1 >= n:
                        return None, ("error", i, "bad escape")
                    nxt = query[i + 1]
                    if nxt == '"' or nxt == "\\":
                        chars.append(nxt)
                        i += 2
                    else:
                        return None, ("error", i, "bad escape")
                else:
                    chars.append(ch)
                    i += 1
            if not closed:
                return None, ("error", start, "unterminated string")
            tokens.append(("STR", start, query[start:i], "".join(chars)))
            continue

        if ("a" <= c <= "z") or ("A" <= c <= "Z") or c == "_":
            start = i
            i += 1
            while i < n:
                ch = query[i]
                if (
                    ("a" <= ch <= "z")
                    or ("A" <= ch <= "Z")
                    or ("0" <= ch <= "9")
                    or ch == "_"
                    or ch == "."
                ):
                    i += 1
                else:
                    break
            raw = query[start:i]
            kw = _KEYWORDS.get(raw)
            if kw is not None:
                tokens.append((kw, start, raw, None))
            else:
                tokens.append(("FIELD", start, raw, raw))
            continue

        return None, ("error", i, f"unexpected character '{c}'")

    tokens.append(("END", n, "", None))
    return tokens, None


def _tok_error(tok) -> tuple:
    if tok[0] == "END":
        return ("error", tok[1], "unexpected end of input")
    return ("error", tok[1], f"unexpected token '{tok[2]}'")


def _parse_to_rpn(tokens: list):
    rpn = []
    op_stack = []
    idx = 0
    expect_expr = True

    while True:
        if expect_expr:
            tok = tokens[idx]
            kind = tok[0]
            if kind == "NOT":
                op_stack.append("NOT")
                idx += 1
            elif kind == "LPAREN":
                op_stack.append("LPAREN")
                idx += 1
            elif kind == "HAS":
                idx += 1
                ftok = tokens[idx]
                if ftok[0] != "FIELD":
                    return None, _tok_error(ftok)
                rpn.append((_OP_HAS, ftok[3], None, None))
                idx += 1
                expect_expr = False
            elif kind == "FIELD":
                field = tok[3]
                idx += 1
                otok = tokens[idx]
                okind = otok[0]
                if okind == "CMP":
                    opcode = _CMP_OPCODES[otok[3]]
                    idx += 1
                    ltok = tokens[idx]
                    if ltok[0] != "INT" and ltok[0] != "STR":
                        return None, _tok_error(ltok)
                    lit = ltok[3]
                    rpn.append((opcode, field, lit, type(lit)))
                    idx += 1
                    expect_expr = False
                elif okind == "IN":
                    idx += 1
                    btok = tokens[idx]
                    if btok[0] != "LBRACK":
                        return None, _tok_error(btok)
                    idx += 1
                    lits = set()
                    while True:
                        ltok = tokens[idx]
                        if ltok[0] != "INT" and ltok[0] != "STR":
                            return None, _tok_error(ltok)
                        lits.add(ltok[3])
                        idx += 1
                        sep = tokens[idx]
                        skind = sep[0]
                        if skind == "COMMA":
                            idx += 1
                        elif skind == "RBRACK":
                            idx += 1
                            break
                        else:
                            return None, _tok_error(sep)
                    rpn.append((_OP_IN, field, lits, None))
                    expect_expr = False
                else:
                    return None, _tok_error(otok)
            else:
                return None, _tok_error(tok)
        else:
            while op_stack and op_stack[-1] == "NOT":
                op_stack.pop()
                if rpn and rpn[-1][0] == _OP_NOT:
                    rpn.pop()
                else:
                    rpn.append((_OP_NOT, None, None, None))

            tok = tokens[idx]
            kind = tok[0]
            if kind == "AND":
                while op_stack and op_stack[-1] == "AND":
                    op_stack.pop()
                    rpn.append((_OP_AND, None, None, None))
                op_stack.append("AND")
                idx += 1
                expect_expr = True
            elif kind == "OR":
                while op_stack and (op_stack[-1] == "AND" or op_stack[-1] == "OR"):
                    op = op_stack.pop()
                    rpn.append((_OP_AND if op == "AND" else _OP_OR, None, None, None))
                op_stack.append("OR")
                idx += 1
                expect_expr = True
            elif kind == "RPAREN":
                while op_stack and (op_stack[-1] == "AND" or op_stack[-1] == "OR"):
                    op = op_stack.pop()
                    rpn.append((_OP_AND if op == "AND" else _OP_OR, None, None, None))
                if not op_stack or op_stack[-1] != "LPAREN":
                    return None, _tok_error(tok)
                op_stack.pop()
                idx += 1
            elif kind == "END":
                while op_stack and (op_stack[-1] == "AND" or op_stack[-1] == "OR"):
                    op = op_stack.pop()
                    rpn.append((_OP_AND if op == "AND" else _OP_OR, None, None, None))
                if op_stack:
                    return None, _tok_error(tok)
                break
            else:
                return None, _tok_error(tok)

    return rpn, None


def filter_records(query: str, records: list[dict]) -> tuple:
    tokens, err = _lex(query)
    if err is not None:
        return err

    rpn, err = _parse_to_rpn(tokens)
    if err is not None:
        return err

    matched = []
    missing = _MISSING
    stack = []

    for rec_idx, rec in enumerate(records):
        stack.clear()
        rec_get = rec.get
        for op, field, arg, lit_type in rpn:
            if op == _OP_NOT:
                stack[-1] = 2 - stack[-1]
            elif op == _OP_AND:
                b = stack.pop()
                if b < stack[-1]:
                    stack[-1] = b
            elif op == _OP_OR:
                b = stack.pop()
                if b > stack[-1]:
                    stack[-1] = b
            elif op == _OP_HAS:
                stack.append(2 if field in rec else 0)
            elif op == _OP_EQ:
                v = rec_get(field, missing)
                stack.append(1 if v is missing else (2 if v == arg else 0))
            elif op == _OP_NE:
                v = rec_get(field, missing)
                stack.append(1 if v is missing else (2 if v != arg else 0))
            elif op == _OP_LT:
                v = rec_get(field, missing)
                stack.append(
                    1 if (v is missing or type(v) is not lit_type) else (2 if v < arg else 0)
                )
            elif op == _OP_LE:
                v = rec_get(field, missing)
                stack.append(
                    1 if (v is missing or type(v) is not lit_type) else (2 if v <= arg else 0)
                )
            elif op == _OP_GT:
                v = rec_get(field, missing)
                stack.append(
                    1 if (v is missing or type(v) is not lit_type) else (2 if v > arg else 0)
                )
            elif op == _OP_GE:
                v = rec_get(field, missing)
                stack.append(
                    1 if (v is missing or type(v) is not lit_type) else (2 if v >= arg else 0)
                )
            else:  # _OP_IN
                v = rec_get(field, missing)
                stack.append(1 if v is missing else (2 if v in arg else 0))

        if stack[0] == 2:
            matched.append(rec_idx)

    return ("ok", matched)

import math
import re

_PRINCIPAL_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,2})?")
_RATE_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,6})?")


def _format_cents(cents: int) -> str:
    dollars, rem = divmod(cents, 100)
    return f"{dollars}.{rem:02d}"


def _round_half_to_even(numerator: int, denominator: int) -> int:
    quot, rem = divmod(numerator, denominator)
    twice_rem = rem * 2
    if twice_rem > denominator:
        return quot + 1
    if twice_rem < denominator:
        return quot
    return quot + (quot & 1)


def amortize(
    principal: str, annual_rate_pct: str, months: int
) -> list[tuple[str, str, str]]:
    if not isinstance(principal, str) or not _PRINCIPAL_RE.fullmatch(principal):
        raise ValueError("Invalid principal format")
    if not isinstance(annual_rate_pct, str) or not _RATE_RE.fullmatch(annual_rate_pct):
        raise ValueError("Invalid annual_rate_pct format")
    if not isinstance(months, int) or isinstance(months, bool) or not (1 <= months <= 1200):
        raise ValueError("months must be an integer between 1 and 1200")

    if "." in principal:
        p_int, p_frac = principal.split(".")
        p_cents = int(p_int.lstrip("0") or "0") * 100 + int(p_frac.ljust(2, "0"))
    else:
        p_cents = int(principal.lstrip("0") or "0") * 100

    if p_cents <= 0:
        raise ValueError("principal must be > 0")

    if "." in annual_rate_pct:
        r_int, r_frac = annual_rate_pct.split(".")
        scale = 10 ** len(r_frac)
        rate_scaled = int(r_int.lstrip("0") or "0") * scale + int(r_frac)
    else:
        scale = 1
        rate_scaled = int(annual_rate_pct.lstrip("0") or "0")

    if rate_scaled > 100 * scale:
        raise ValueError("annual_rate_pct must be <= 100")

    # Monthly rate m = p / q in lowest terms
    denom = 1200 * scale
    g = math.gcd(rate_scaled, denom)
    p = rate_scaled // g
    q = denom // g

    # Level payment PAY in cents, rounded up to whole cents
    if p == 0:
        pay_cents = (p_cents + months - 1) // months
    else:
        # A_cents = p_cents * m / (1 - (q / (q + p)) ** months)
        #         = p_cents * p * (q + p)**months / (q * ((q + p)**months - q**months))
        qp_pow = pow(q + p, months)
        q_pow = pow(q, months)
        num = p_cents * p * qp_pow
        den = q * (qp_pow - q_pow)
        pay_cents = (num + den - 1) // den

    schedule: list[tuple[str, str, str]] = []
    bal_cents = p_cents

    for t in range(1, months + 1):
        int_cents = 0 if p == 0 else _round_half_to_even(bal_cents * p, q)

        if t == months or bal_cents + int_cents <= pay_cents:
            actual_pay = bal_cents + int_cents
            bal_cents = 0
            schedule.append(
                (_format_cents(actual_pay), _format_cents(int_cents), "0.00")
            )
            break

        bal_cents -= pay_cents - int_cents
        schedule.append(
            (
                _format_cents(pay_cents),
                _format_cents(int_cents),
                _format_cents(bal_cents),
            )
        )

    return schedule

def decimal_to_half_bits(s: str) -> int:
    """Convert an exact decimal literal string to its IEEE 754 binary16 bit pattern."""
    if not isinstance(s, str) or not s or not s.isascii():
        raise ValueError("invalid decimal literal")

    n = len(s)
    pos = 0
    sign_bit = 0
    c0 = s[0]
    if c0 == "+" or c0 == "-":
        if c0 == "-":
            sign_bit = 0x8000
        pos = 1
        if pos == n:
            raise ValueError("invalid decimal literal")

    # Split mantissa and optional exponent; since s is ASCII, .isdigit() matches [0-9]+ only.
    e_pos = s.find("e", pos)
    if e_pos == -1:
        e_pos = s.find("E", pos)

    if e_pos != -1:
        mant = s[pos:e_pos]
        exp_pos = e_pos + 1
        exp_neg = False
        if exp_pos < n and (s[exp_pos] == "+" or s[exp_pos] == "-"):
            exp_neg = s[exp_pos] == "-"
            exp_pos += 1
        exp_digits = s[exp_pos:]
        if not exp_digits.isdigit():
            raise ValueError("invalid decimal literal")
    else:
        mant = s[pos:]
        exp_neg = False
        exp_digits = ""

    if not mant:
        raise ValueError("invalid decimal literal")

    dot_pos = mant.find(".")
    if dot_pos == -1:
        if not mant.isdigit():
            raise ValueError("invalid decimal literal")
        int_part = mant
        frac_part = ""
    else:
        int_part = mant[:dot_pos]
        frac_part = mant[dot_pos + 1 :]
        if not int_part and not frac_part:
            raise ValueError("invalid decimal literal")
        if int_part and not int_part.isdigit():
            raise ValueError("invalid decimal literal")
        if frac_part and not frac_part.isdigit():
            raise ValueError("invalid decimal literal")

    # Parse exponent while clamping extreme magnitudes safely beyond any mantissa offset.
    if exp_digits:
        exp_stripped = exp_digits.lstrip("0")
        if not exp_stripped:
            lit_exp = 0
        elif len(exp_stripped) > 15:
            clamp = n + 1000
            lit_exp = -clamp if exp_neg else clamp
        else:
            lit_exp = int(exp_stripped)
            if exp_neg:
                lit_exp = -lit_exp
    else:
        lit_exp = 0

    # Every binary16 midpoint is an integer multiple of 2**-25 = 5**25 * 10**-25
    # (at most 22 significant decimal digits). Keeping 40 significant digits plus
    # one sticky digit preserves the exact ordering against every binary16 midpoint.
    max_sig = 40
    int_stripped = int_part.lstrip("0")
    if int_stripped:
        if len(int_stripped) >= max_sig:
            head = int_stripped[:max_sig]
            has_rem = bool(int_stripped[max_sig:].lstrip("0") or frac_part.lstrip("0"))
        else:
            need = max_sig - len(int_stripped)
            head = int_stripped + frac_part[:need]
            has_rem = bool(frac_part[need:].lstrip("0"))
        base_exp = len(int_stripped) - len(head)
    else:
        frac_stripped = frac_part.lstrip("0")
        if not frac_stripped:
            return sign_bit
        leading_zeros = len(frac_part) - len(frac_stripped)
        head = frac_stripped[:max_sig]
        has_rem = bool(frac_stripped[max_sig:].lstrip("0"))
        base_exp = -leading_zeros - len(head)

    if has_rem:
        head += "1"
        base_exp -= 1
    else:
        trimmed = head.rstrip("0")
        base_exp += len(head) - len(trimmed)
        head = trimmed

    exp10 = base_exp + lit_exp
    # 10**log10_floor <= v < 10**(log10_floor + 1)
    log10_floor = len(head) - 1 + exp10
    if log10_floor >= 5:
        return sign_bit | 0x7C00
    if log10_floor <= -9:
        return sign_bit

    mant_int = int(head)
    if exp10 >= 0:
        num = mant_int * (10 ** exp10)
        den = 1
    else:
        num = mant_int
        den = 10 ** (-exp10)

    # 65520 is the midpoint between 65504 (0x7BFF, odd) and 65536 (0x7C00, even).
    if num >= 65520 * den:
        return sign_bit | 0x7C00

    # Subnormal range: v < 2**-14. Spacing is uniformly 2**-24 across [0, 2**-14],
    # and the bit pattern equals the rounded multiple of 2**-24 (including 1024 == 0x0400).
    if (num << 14) < den:
        q, r = divmod(num << 24, den)
        two_r = r << 1
        if two_r > den or (two_r == den and (q & 1)):
            q += 1
        return sign_bit | q

    # Normal range: 2**-14 <= v < 65520. Find k = floor(log2(num / den)), -14 <= k <= 15.
    bl_diff = num.bit_length() - den.bit_length()
    if bl_diff >= 0:
        k = bl_diff if num >= (den << bl_diff) else bl_diff - 1
    else:
        k = bl_diff if (num << (-bl_diff)) >= den else bl_diff - 1

    shift = 10 - k
    if shift >= 0:
        scaled_num = num << shift
        scaled_den = den
    else:
        scaled_num = num
        scaled_den = den << (-shift)

    q, r = divmod(scaled_num, scaled_den)
    two_r = r << 1
    if two_r > scaled_den or (two_r == scaled_den and (q & 1)):
        q += 1

    return sign_bit | (((k + 14) << 10) + q)

from bisect import bisect_left


def run_ops(ops: list[tuple]) -> list:
    vals = sorted({op[1] for op in ops if op[0] == "add"})
    m = len(vals)
    val_to_idx = {v: i + 1 for i, v in enumerate(vals)}
    max_pow2 = 1 << (m.bit_length() - 1) if m > 0 else 0

    bit = [0] * (m + 1)
    counts = [0] * (m + 1)
    total_size = 0
    distinct_count = 0

    # Positive idx records an add; negative idx records a remove.
    undo_log: list[int] = []
    cp_stack: list[int] = []
    cp_pos: dict[int, int] = {}
    next_cp_id = 0

    out: list = []
    append_out = out.append

    for op in ops:
        kind = op[0]

        if kind == "add":
            idx = val_to_idx[op[1]]
            if counts[idx] == 0:
                distinct_count += 1
            counts[idx] += 1
            total_size += 1
            i = idx
            while i <= m:
                bit[i] += 1
                i += i & -i
            undo_log.append(idx)
            append_out(total_size)

        elif kind == "remove":
            idx = val_to_idx.get(op[1], 0)
            if idx == 0 or counts[idx] == 0:
                append_out(False)
            else:
                counts[idx] -= 1
                if counts[idx] == 0:
                    distinct_count -= 1
                total_size -= 1
                i = idx
                while i <= m:
                    bit[i] -= 1
                    i += i & -i
                undo_log.append(-idx)
                append_out(True)

        elif kind == "checkpoint":
            next_cp_id += 1
            cp_stack.append(next_cp_id)
            cp_pos[next_cp_id] = len(undo_log)
            append_out(next_cp_id)

        elif kind == "rollback":
            c = op[1]
            target_len = cp_pos.get(c)
            if target_len is None:
                append_out("BADCP")
            else:
                while cp_stack[-1] > c:
                    del cp_pos[cp_stack.pop()]

                while len(undo_log) > target_len:
                    u = undo_log.pop()
                    if u > 0:
                        counts[u] -= 1
                        if counts[u] == 0:
                            distinct_count -= 1
                        total_size -= 1
                        i = u
                        while i <= m:
                            bit[i] -= 1
                            i += i & -i
                    else:
                        idx = -u
                        if counts[idx] == 0:
                            distinct_count += 1
                        counts[idx] += 1
                        total_size += 1
                        i = idx
                        while i <= m:
                            bit[i] += 1
                            i += i & -i

                append_out(total_size)

        elif kind == "median":
            if total_size == 0:
                append_out(None)
            else:
                k = (total_size + 1) >> 1
                pos = 0
                step = max_pow2
                while step:
                    nxt = pos + step
                    if nxt <= m and bit[nxt] < k:
                        k -= bit[nxt]
                        pos = nxt
                    step >>= 1
                append_out(vals[pos])

        elif kind == "count_less":
            i = bisect_left(vals, op[1])
            s = 0
            while i > 0:
                s += bit[i]
                i &= i - 1
            append_out(s)

        elif kind == "distinct":
            append_out(distinct_count)

    return out

from collections import OrderedDict
import heapq


def run_cache(capacity, ops):
    if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity < 1:
        raise ValueError("capacity must be a positive int")

    store = OrderedDict()  # key -> [value, version]; oldest use first
    heap = []  # min-heap of (expires_at, version, key)
    out = []
    last_t = None
    version = 0

    heappush = heapq.heappush
    heappop = heapq.heappop
    store_get = store.get
    move_to_end = store.move_to_end
    popitem = store.popitem
    out_append = out.append

    for op in ops:
        if len(op) < 2:
            raise ValueError("invalid operation")
        kind, t = op[0], op[1]
        if isinstance(t, bool) or not isinstance(t, int):
            raise ValueError("timestamp must be an int")
        if last_t is not None and t < last_t:
            raise ValueError("operations must have non-decreasing timestamps")
        last_t = t

        if kind == "put":
            _, _, key, value, ttl = op
            if ttl is not None and (
                isinstance(ttl, bool) or not isinstance(ttl, int) or ttl < 1
            ):
                raise ValueError("ttl must be None or a positive int")

            while heap and heap[0][0] <= t:
                _, exp_ver, exp_key = heappop(heap)
                exp_entry = store_get(exp_key)
                if exp_entry is not None and exp_entry[1] == exp_ver:
                    del store[exp_key]

            version += 1
            entry = store_get(key)
            if entry is not None:
                entry[0] = value
                entry[1] = version
                move_to_end(key)
            else:
                if len(store) >= capacity:
                    popitem(last=False)
                store[key] = [value, version]

            if ttl is not None:
                heappush(heap, (t + ttl, version, key))

        elif kind == "get":
            _, _, key = op
            while heap and heap[0][0] <= t:
                _, exp_ver, exp_key = heappop(heap)
                exp_entry = store_get(exp_key)
                if exp_entry is not None and exp_entry[1] == exp_ver:
                    del store[exp_key]

            entry = store_get(key)
            if entry is None:
                out_append(None)
            else:
                move_to_end(key)
                out_append(entry[0])

        elif kind == "size":
            _, _ = op
            while heap and heap[0][0] <= t:
                _, exp_ver, exp_key = heappop(heap)
                exp_entry = store_get(exp_key)
                if exp_entry is not None and exp_entry[1] == exp_ver:
                    del store[exp_key]

            out_append(len(store))

        else:
            raise ValueError("unknown operation %r" % (kind,))

    return out

import heapq


def window_medians(readings, k):
    if isinstance(k, bool) or not isinstance(k, int) or k < 1:
        raise ValueError("k must be a positive int")

    heappush = heapq.heappush
    heappop = heapq.heappop

    low = []       # max-heap via negation: smaller half, -low[0] is the lower median
    high = []      # min-heap: larger half
    delayed = {}   # value -> pending lazy deletion count
    low_size = 0   # live element count in low
    high_size = 0  # live element count in high
    out = []

    def prune(heap, sign):
        # Drop lazily deleted values sitting at the top of a heap.
        while heap:
            val = sign * heap[0]
            cnt = delayed.get(val, 0)
            if not cnt:
                break
            if cnt == 1:
                del delayed[val]
            else:
                delayed[val] = cnt - 1
            heappop(heap)

    def rebalance():
        nonlocal low_size, high_size
        # Invariant: low_size == high_size or low_size == high_size + 1,
        # and both heap tops (when non-empty) are guaranteed live.
        if low_size > high_size + 1:
            heappush(high, -heappop(low))
            low_size -= 1
            high_size += 1
            prune(low, -1)
        elif low_size < high_size:
            heappush(low, -heappop(high))
            high_size -= 1
            low_size += 1
            prune(high, 1)

    def add(x):
        nonlocal low_size, high_size
        if not low or x <= -low[0]:
            heappush(low, -x)
            low_size += 1
        else:
            heappush(high, x)
            high_size += 1
        rebalance()

    def remove(x):
        nonlocal low_size, high_size
        delayed[x] = delayed.get(x, 0) + 1
        if x <= -low[0]:
            low_size -= 1
            if x == -low[0]:
                prune(low, -1)
        else:
            high_size -= 1
            if x == high[0]:
                prune(high, 1)
        rebalance()

    for i, x in enumerate(readings):
        if i >= k and readings[i - k] is not None:
            remove(readings[i - k])
        if x is not None:
            add(x)
        out.append(-low[0] if low_size else None)

    return out

TWO_CHAR_OPS = ("==", "!=", "<=", ">=", "->")
ONE_CHAR_OPS = "<>=+-*/(),"
ESCAPES = {'"': '"', "\\": "\\", "n": "\n", "t": "\t"}


def _is_digit(ch):
    return "0" <= ch <= "9"


def _is_ident_start(ch):
    return ch == "_" or "a" <= ch <= "z" or "A" <= ch <= "Z"


def _is_ident_char(ch):
    return _is_ident_start(ch) or _is_digit(ch)


def tokenize(src):
    tokens = []
    n = len(src)
    i, line, col = 0, 1, 1

    def fail(at_line, at_col, message):
        raise ValueError("line %d col %d: %s" % (at_line, at_col, message))

    while i < n:
        ch = src[i]

        if ch == "\n":
            i += 1
            line += 1
            col = 1
            continue
        if ch == " " or ch == "\t":
            i += 1
            col += 1
            continue
        if ch == "#":
            end = src.find("\n", i)
            if end == -1:
                col += n - i
                i = n
            else:
                col += end - i
                i = end
            continue

        if _is_digit(ch):
            j = i
            while j < n and _is_digit(src[j]):
                j += 1
            is_float = False
            if j + 1 < n and src[j] == "." and _is_digit(src[j + 1]):
                j += 2
                while j < n and _is_digit(src[j]):
                    j += 1
                is_float = True
            if j < n and (src[j] == "e" or src[j] == "E"):
                k = j + 1
                if k < n and (src[k] == "+" or src[k] == "-"):
                    k += 1
                if k < n and _is_digit(src[k]):
                    j = k + 1
                    while j < n and _is_digit(src[j]):
                        j += 1
                    is_float = True
            text = src[i:j]
            tokens.append(("NUMBER", float(text) if is_float else int(text), line, col))
            col += j - i
            i = j
            continue

        if _is_ident_start(ch):
            j = i
            while j < n and _is_ident_char(src[j]):
                j += 1
            tokens.append(("IDENT", src[i:j], line, col))
            col += j - i
            i = j
            continue

        if ch == '"':
            j = i + 1
            chars = []
            while True:
                if j >= n or src[j] == "\n":
                    fail(line, col, "unterminated string")
                c = src[j]
                if c == '"':
                    j += 1
                    break
                if c == "\\":
                    if j + 1 >= n or src[j + 1] == "\n":
                        fail(line, col, "unterminated string")
                    if src[j + 1] not in ESCAPES:
                        fail(line, col + (j - i), "bad escape")
                    chars.append(ESCAPES[src[j + 1]])
                    j += 2
                    continue
                chars.append(c)
                j += 1
            tokens.append(("STRING", "".join(chars), line, col))
            col += j - i
            i = j
            continue

        if src[i:i + 2] in TWO_CHAR_OPS:
            tokens.append(("OP", src[i:i + 2], line, col))
            i += 2
            col += 2
            continue
        if ch in ONE_CHAR_OPS:
            tokens.append(("OP", ch, line, col))
            i += 1
            col += 1
            continue

        fail(line, col, "unexpected character %r" % (ch,))

    return tokens
